-- §SHED_FILM_V2_PATCH (2026-11-02): Shed_film.db = Modeller walked-MEP export (711 rows). Export carries a 1-row spatial_structure with no room; the Viewer room graph / escape route needs the compiled IfcSpace RM_Level_1_1 (copied from Shed_wholewalk.db) + the walkable raster (identical to Shed_wholewalk's, built by scripts/build_storey_walkable_raster.js). Idempotent.
DROP TABLE IF EXISTS spatial_structure;
CREATE TABLE spatial_structure (guid TEXT PRIMARY KEY, type TEXT NOT NULL, name TEXT, parent_guid TEXT, object_type TEXT, predefined_type TEXT, elevation REAL, center_x REAL, center_y REAL, center_z REAL, size_x REAL, size_y REAL, size_z REAL, room_guid TEXT);
INSERT INTO spatial_structure VALUES('1NYDQsVbU0AcCO26AAD0JC','IfcBuilding','Building',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO spatial_structure VALUES('0BtqBaYD0tB5DiKBAAD0JK','IfcBuildingStorey','Level 1','1NYDQsVbU0AcCO26AAD0JC',NULL,NULL,0.0,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO spatial_structure VALUES('STC_Level_1','IfcBuildingStorey','Level 1',NULL,'COMPILED',NULL,NULL,NULL,NULL,0.989406216045724096,NULL,NULL,NULL,NULL);
INSERT INTO spatial_structure VALUES('RM_Level_1_1','IfcSpace','⚠ Level 1 R1','0BtqBaYD0tB5DiKBAAD0JK','COMPILED','SUSPECT_OPEN',NULL,-661.081634414062477,-103.318180014194496,1.98345655931266673,39.4335324999999983,15.1129979999999992,2.0,'RM_Level_1_1');
CREATE TABLE IF NOT EXISTS storey_walkable_raster (storey TEXT PRIMARY KEY, res REAL, x0 REAL, y0 REAL, cols INTEGER, rows INTEGER, bits BLOB);
INSERT OR REPLACE INTO storey_walkable_raster (storey,res,x0,y0,cols,rows,bits) VALUES ('Level 1',0.25,-681.9984,-112.0747,168,71,X'');

-- §SHED_FILM_GEOREF (2026-11-02, owner chose "Geocode the address"): the drawings state no coordinate (the DXF headers carry AutoCAD's factory default
-- $LATITUDE 37.795 / $LONGITUDE -122.394 / $NORTHDIRECTION 0, not a site fact). Title-block address "Bongkura, Srimontokathi, Jhalokathi" geocoded to the village
-- Srimantakati, en.wikipedia.org/wiki/Srimantakati 22°37'N 90°7'E (1 arc-minute; "Bongkura" not found in OSM Nominatim or Wikipedia; Jhalokati town, OSM 22.6426 90.1990, is 8.6 km east).
-- True north is NOT stated anywhere (no north arrow found): default_zero, which cpe_sun_compass.js logs as §SUN_COMPASS_NOTE (sun correct, building rotation unverified).
DELETE FROM project_metadata WHERE key IN ('site_latitude','site_longitude','site_latlong_source','true_north_angle','true_north_source');
INSERT INTO project_metadata (key,value) VALUES ('site_latitude','22.617'),('site_longitude','90.117'),
  ('site_latlong_source','geocoded:title-block address -> Srimantakati (Wikipedia 22d37mN 90d7mE)'),
  ('true_north_angle','0'),('true_north_source','default_zero');
-- §SHED_FILM_STOREY (2026-11-02): the walked-MEP Export leaves every element on storey 'Unknown' and storey_elevation empty, so the load-path pick (lp_chain.js _hasStorey) found 0 candidates
-- (§LOADPATH_BEARING candidates=0 on the first v3 bake). The building has ONE storey, Level 1 (spatial_structure 0BtqBaYD0tB5DiKBAAD0JK, elevation 0.0), same as Shed_wholewalk.db.
UPDATE elements_meta SET storey='Level 1' WHERE storey='Unknown' AND ifc_class<>'IfcOpeningElement';
DELETE FROM storey_elevation WHERE guid='0BtqBaYD0tB5DiKBAAD0JK';
INSERT INTO storey_elevation (guid,name,elevation_attr_m,placement_z_m) VALUES ('0BtqBaYD0tB5DiKBAAD0JK','Level 1',0.0,0.0);
-- §SHED_FILM_NAME (2026-11-02): the reopen + walk export names the building after the FILE (ShedFresh.db -> SHEDFRESHDB); the drawings state @SET=SHED on all 9 marked sheets
-- (and the first Convert export carries building_name=SHED). Restore the stated name. Reported to the Modeller lane (export-after-reopen naming).
UPDATE project_metadata SET value='SHED' WHERE key='building_name';
UPDATE project_metadata SET value='SHED.ifc' WHERE key='source_file';
-- The Viewer shows the name carried on every row (elements_meta.building 711 rows, component_geometries.building 267 rows), not project_metadata: restore SHED there too.
UPDATE elements_meta SET building='SHED' WHERE building='SHEDFRESHDB';
UPDATE component_geometries SET building='SHED' WHERE building='SHEDFRESHDB';
